#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { parseWav } from "../studio/core/wavToDsound.js";
import { encodeVoxPcmSegments, voxPcmToPreviewSamples } from "../studio/core/colecoVoxPcm.js";

const input = path.resolve(process.argv[2] || "tmp/number-game-voices");
const output = path.resolve(process.argv[3] || "artifacts/number-game-voices");
const words = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "uhoh"];
fs.mkdirSync(output, { recursive: true });

const asm = [
  "; Spoken digits generated by tools/synthesize-number-game-voices.py and",
  "; converted by tools/build-number-game-voices.mjs (adaptive tiny-balanced)."
];
const preview = [];
for (const word of words) {
  const bytes = fs.readFileSync(path.join(input, `${word}.wav`));
  const wav = parseWav(bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength));
  const prefix = word === "uhoh" ? "Uhoh" : word[0].toUpperCase() + word.slice(1);
  const encoded = encodeVoxPcmSegments(wav.samples, wav.sampleRate, {
    segmentMilliseconds: 140,
    quality: "adaptive",
    minimumQuality: "tiny",
    maximumQuality: "balanced",
    gainPercent: 100,
    dither: true,
    labelPrefix: `Vox${prefix}`
  });
  asm.push(`Say${prefix}:`);
  for (const part of encoded.parts) {
    asm.push(`  dw ${part.label}`, `  db ${part.repeatDelay},${part.boundaryDelay}`);
  }
  asm.push("  dw 0,0");
  encoded.parts.forEach((part) => {
    asm.push(`${part.label}:`);
    for (let offset = 0; offset < part.bytes.length; offset += 24) {
      asm.push(`  db ${Array.from(part.bytes.slice(offset, offset + 24)).join(",")}`);
    }
  });
  preview.push(...voxPcmToPreviewSamples(encoded.parts, 22050));
  preview.push(...new Array(Math.round(22050 * 0.36)).fill(0));
}
asm.push("SayTable:", "  dw SayZero,SayOne,SayTwo,SayThree,SayFour,SayFive,SaySix,SaySeven,SayEight,SayNine", "");
fs.writeFileSync(path.join(output, "number-game-voices.asm"), `${asm.join("\n")}\n`);
fs.writeFileSync(path.join(output, "number-game-voice-preview.wav"), encodeWav(Float32Array.from(preview), 22050));

function encodeWav(samples, sampleRate) {
  const result = Buffer.alloc(44 + samples.length * 2);
  result.write("RIFF", 0); result.writeUInt32LE(result.length - 8, 4); result.write("WAVE", 8);
  result.write("fmt ", 12); result.writeUInt32LE(16, 16); result.writeUInt16LE(1, 20);
  result.writeUInt16LE(1, 22); result.writeUInt32LE(sampleRate, 24);
  result.writeUInt32LE(sampleRate * 2, 28); result.writeUInt16LE(2, 32); result.writeUInt16LE(16, 34);
  result.write("data", 36); result.writeUInt32LE(samples.length * 2, 40);
  for (let index = 0; index < samples.length; index += 1) {
    result.writeInt16LE(Math.round(Math.max(-1, Math.min(1, samples[index])) * 32767), 44 + index * 2);
  }
  return result;
}
